function saveCustomBoard(){try{const rows=$('#customRows').value.trim().toUpperCase().split(/\s+/).filter(Boolean);if(JSON.stringify(rows)!==JSON.stringify(draftBoard.rows))throw Error('行布局已变化，请先点击“按布局生成”再编辑音高。');const actions={};$$('[data-action-pitches]').forEach(n=>{const k=n.dataset.actionPitches;actions[k]={label:$(`[data-action-label="${k}"]`).value,pitches:n.value.trim().split(/[\s,+]+/).filter(Boolean).map(Boards.pitch)};});const name=$('#customBoardName').value.trim();if(!name)throw Error('请填写琴盘名称');const board=Boards.validate({id:activeBoard.id.startsWith('custom-')?activeBoard.id:'custom-'+newSheetId(),name,rows,actions,strumMs:Number($('#customStrum').value),warning:'自定义映射 · 按你的设置模拟发声，不代表已验证的游戏预设。'});const existing=userBoards.findIndex(b=>b.id===board.id);if(existing>=0)userBoards[existing]=board;else userBoards.push(board);localStorage.setItem('keymelody.customBoards.v1',JSON.stringify(userBoards));$('#boardDialog').close();fillBoardChoices();loadBoardDemo(board);toast('自定义琴盘已保存，可开始测试。');}catch(e){toast(e.message);}}
function loadBoardDemo(board){const keys=board.rows.join('');const source=[...keys].map(k=>k+':1').join(' ');const demo={id:'demo-'+board.id,name:board.name+' · 键位测试',format:'letters',source,bpm:90,timing:'confirmed',defaultBeats:1,board,targetBoard:board,tag:'测试'};loadSong(demo);}
function saveAdaptation(){const entry={id:'sheet-'+newSheetId(),name:song.name+' · '+activeBoard.name,format:'json',source:JSON.stringify({events}),bpm:Number($('#bpm').value),defaultBeats:1,timing:song.timing,board:activeBoard,targetBoard:activeBoard,original:{format:song.format,source:song.source,board:song.board||Boards.standard,options:song.importOptions},tag:'适配'};custom.push(entry);songs=[...BUILTINS,...custom];const ok=persist();loadSong(entry);rememberSong(entry);toast(ok?'已另存适配版，原曲谱保留。':'仅本次会话可用，请导出备份。');}
function setupBoardControls(){fillBoardChoices();$('#targetBoard').value=activeBoard.id;$('#targetBoard').onchange=()=>{try{loadSong(song,profileOf($('#targetBoard').value));}catch(e){toast(e.message);$('#targetBoard').value=activeBoard.id;}};$('#boardDemo').onclick=()=>loadBoardDemo(profileOf($('#targetBoard').value));$('#boardEditor').onclick=openBoardEditor;$('#generateBoard').onclick=rebuildDraft;$('#saveCustomBoard').onclick=saveCustomBoard;$('#saveAdaptation').onclick=saveAdaptation;$('#timbre').onchange=()=>{pause();stopAudio();prefs.timbre=soundId();captureBoardState();describeSound();prepareSound();updateButton();};for(const id of ['melodyVolume','chordVolume'])$('#'+id).oninput=()=>{prefs[id]=Number($('#'+id).value);captureBoardState();};$('#practicePart').onchange=()=>loadSong(song,activeBoard);for(const id of ['convertFold','convertChordMatch'])$('#'+id).onchange=()=>loadSong(song,activeBoard);for(const id of ['sourceBoard','importTargetBoard','importFold','importChordMatch'])$('#'+id).onchange=()=>{stopAudio();previewParse();};}

function soundId(){return $('#timbre').value||'piano';}
function soundStatus(message){$('#soundStatus').textContent=message;$('#soundStatus').dataset.state='info';}
function describeSound(){const id=soundId();if(!soundLibrary||!SoundBank.isSample(id)){soundStatus('轻量合成音色 · 无需下载');return;}const info=soundLibrary.manifest?.instruments.find(i=>i.id===id);soundStatus((soundLibrary.ready(id)?'已就绪':'首次使用时加载')+(info?' · '+(info.bytes/1048576).toFixed(2)+' MB':'')+' · CC0采样');}
async function prepareSound(id=soundId()){
 initAudio();if(!soundLibrary||!SoundBank.isSample(id))return true;if(!audio){soundStatus('此浏览器无法启用声音，可关闭音效继续练习。');return false;}
 try{await soundLibrary.load(id,audio,p=>{if(id===soundId())soundStatus(`正在加载 ${p.completed}/${p.total} · ${(p.bytes/1048576).toFixed(2)} MB`);});if(id===soundId())describeSound();return true;}
 catch(e){if(id===soundId()){$('#timbre').value='piano';$('#settingsTimbre').value='piano';prefs.timbre='piano';captureBoardState();soundStatus('采样加载失败，已切换合成钢琴；可重新选择重试。');$('#soundStatus').dataset.state='error';}return false;}
}
function withSound(action){initAudio();const id=soundId(),intent=audioIntent;if(!soundLibrary||soundLibrary.ready(id))return action();return prepareSound(id).then(()=>{if(intent===audioIntent&&(id===soundId()||soundId()==='piano')&&soundLibrary.ready(soundId()))return action();if(intent===audioIntent){audioStarting=false;updateButton();}});}
function auditionSound(){pause();stopAudio();withSound(()=>{const pitches=[60,64,67,72,67,64,60],board={actions:Object.fromEntries(pitches.map((p,i)=>[i,{type:'note',pitches:[p]}])),strumMs:0};pitches.forEach((_,i)=>tone(String(i),i*.28,false,.4,board));soundStatus((soundLibrary&&SoundBank.isSample(soundId())?'CC0采样':'轻量合成')+' · 试听旋律 C4—E4—G4—C5');});}
function setupSoundControls(){if(!soundLibrary)return;$('#soundPreview').onclick=auditionSound;$('#soundStop').onclick=()=>{pause();stopAudio();describeSound();};$('#soundCredits').onclick=()=>{openDialog('#soundDialog');};soundLibrary.catalog().then(m=>{describeSound();const root=$('#soundSources');root.replaceChildren();m.instruments.forEach(i=>{const row=el('article','sound-source'),title=el('h3','',i.name),credit=el('p','',i.credit),link=el('a','','查看原始来源 ↗');link.href=i.sourceUrl;link.target='_blank';link.rel='noopener noreferrer';row.append(title,credit,el('small','',`CC0 1.0 · ${(i.bytes/1048576).toFixed(2)} MB · ${i.samples.length}个采样`),link);root.append(row);});}).catch(()=>soundStatus('音色清单暂未加载；可使用轻量合成音色。'));}

// Drag the score under the fixed playhead; releasing selects the group at the playhead.
function timelineMetrics(){const rect=canvas.getBoundingClientRect();return {rect,x0:85,px:Math.max(42,(rect.width-85)/7)};}
function eventAtBeat(beat){const r=range();let lo=r.start,hi=r.end;while(lo<hi){const mid=Math.ceil((lo+hi)/2);if(events[mid].beat<=beat)lo=mid;else hi=mid-1;}return lo;}
function timelinePreview(beat){const r=range();position=Math.max(r.startBeat,Math.min(events[r.end].beat,beat));visualPosition=position;index=eventAtBeat(position);status='paused';refreshActive();}
function finishTimelineDrag(e){if(!timelineDrag||e.pointerId!==timelineDrag.id)return;const d=timelineDrag;timelineDrag=null;canvas.classList.remove('dragging');if(d.moved){seek(index);status='paused';setFeedback(`已定位第 ${index+1} 组 · 点击播放继续`,3);}else{const {rect,x0,px}=timelineMetrics(),target=d.beat+(e.clientX-rect.left-x0)/px;seek(eventAtBeat(target));status='paused';setFeedback(`已定位第 ${index+1} 组`,2);}updateButton();refreshActive(true);}
function setupTimelineDrag(){
 canvas.addEventListener('pointerdown',e=>{if(e.button!==0||timelineDrag||!events.length)return;const before=currentBeat();pause();stopAudio();const {px}=timelineMetrics();timelineDrag={id:e.pointerId,x:e.clientX,beat:before,px,moved:false};canvas.setPointerCapture(e.pointerId);canvas.focus({preventScroll:true});e.preventDefault();updateButton();});
 canvas.addEventListener('pointermove',e=>{if(!timelineDrag||e.pointerId!==timelineDrag.id)return;const d=timelineDrag,dx=e.clientX-d.x;if(!d.moved&&Math.abs(dx)<4)return;d.moved=true;canvas.classList.add('dragging');timelinePreview(d.beat-dx/d.px);e.preventDefault();});
 canvas.addEventListener('pointerup',finishTimelineDrag);
 canvas.addEventListener('pointercancel',e=>{if(!timelineDrag||e.pointerId!==timelineDrag.id)return;timelineDrag=null;canvas.classList.remove('dragging');seek(index);status='paused';updateButton();});
 canvas.addEventListener('lostpointercapture',e=>{if(timelineDrag&&e.pointerId===timelineDrag.id){timelineDrag=null;canvas.classList.remove('dragging');seek(index);status='paused';updateButton();}});
 canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const r=range();seek(e.key==='Home'?r.start:e.key==='End'?r.end:index+(e.key==='ArrowRight'?1:-1)*(e.shiftKey?4:1));status='paused';setFeedback(`已定位第 ${index+1} 组`,2);updateButton();});
}

function saveJudgmentRule(key,value){judgment[key]=value;try{localStorage.setItem('keymelody.judgment.v1',JSON.stringify(judgment));}catch(e){toast('判定选项仅在本次会话生效。');}seek(range().start);syncRhythmSettings();updateRuleHint();toast('判定选项已更新，已回到片段开头并重置统计。');}
function setupJudgmentControls(){for(const [id,key] of [['twoKeyChords','twoKeyChords'],['advanceOnWrong','advanceOnWrong'],['settingsTwoKeyChords','twoKeyChords'],['settingsAdvanceOnWrong','advanceOnWrong']]){$('#'+id).checked=judgment[key];$('#'+id).onchange=()=>saveJudgmentRule(key,$('#'+id).checked);}updateRuleHint();}
function updateRuleHint(){$('#judgmentHint').textContent=(judgment.twoKeyChords?'两键兼容已开启：三键以上组任选2个正确键，在250ms内同时按下；其余键不算漏按。':'三键及以上和弦默认需完整按齐。')+(judgment.advanceOnWrong?' 等待模式错按计1次错误并跳至下一组。':' 等待模式错按后停留，直到按对。');}
function selectSettingsTab(tab){$$('[data-settings-tab]').forEach(b=>{const selected=b.dataset.settingsTab===tab;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});for(const name of ['display','layout','practice','sound','support'])$('#settings-'+name).hidden=name!==tab;$('#settingsDialog .dialog-scroll').scrollTop=0;}
function persistRhythm(){try{localStorage.setItem('keymelody.rhythm.v1',JSON.stringify(rhythmPrefs));}catch(e){toast('节奏设置仅在本次会话生效。');}}
function syncRhythmSettings(){const w=Rhythm.windowFor(rhythmPrefs.level);$('#tolerance').value=$('#settingsTolerance').value=rhythmPrefs.level;$('#windowHint').textContent=`Perfect ±${w.perfect} / Good ±${w.good} / Bad ±${w.bad} ms`;$('#offset').value=rhythmPrefs.offset;$('#offsetValue').textContent=(rhythmPrefs.offset>0?'+':'')+rhythmPrefs.offset+' ms';for(const [id,key] of [['twoKeyChords','twoKeyChords'],['advanceOnWrong','advanceOnWrong'],['settingsTwoKeyChords','twoKeyChords'],['settingsAdvanceOnWrong','advanceOnWrong']])$('#'+id).checked=judgment[key];}
function changeDifficulty(level){if(!Object.hasOwn(Rhythm.WINDOWS,level))return;rhythmPrefs.level=level;persistRhythm();seek(range().start);syncRhythmSettings();toast('已切换为'+Rhythm.windowFor(level).name+'判定，本轮统计已重置。');}
function applyOffset(value){const next=Math.max(-300,Math.min(300,Math.round(value)||0));if(next!==rhythmPrefs.offset){pause();rhythmPrefs.offset=prefs.offset=next;persistRhythm();seek(range().start);savePrefs();}syncRhythmSettings();}
function syncSoundSettings(){$('#settingsTimbre').value=soundId();$('#settingsMelodyVolume').value=$('#melodyVolume').value;$('#settingsChordVolume').value=$('#chordVolume').value;$('#settingsSoundToggle').checked=$('#soundToggle').checked;}
function setupRhythmSettings(){syncRhythmSettings();const soundSelect=$('#settingsTimbre');soundSelect.innerHTML=$('#timbre').innerHTML;syncSoundSettings();$('#settingsTolerance').onchange=()=>changeDifficulty($('#settingsTolerance').value);$$('[data-settings-tab]').forEach(b=>{b.onclick=()=>selectSettingsTab(b.dataset.settingsTab);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=$$('[data-settings-tab]'),i=tabs.indexOf(b),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectSettingsTab(tabs[next].dataset.settingsTab);tabs[next].focus();};});$('#displaySettings').onclick=()=>openSettings('layout');$('#settingsTimbre').onchange=()=>{$('#timbre').value=soundSelect.value;$('#timbre').onchange();};for(const [id,source] of [['settingsMelodyVolume','melodyVolume'],['settingsChordVolume','chordVolume']])$('#'+id).oninput=()=>{$('#'+source).value=$('#'+id).value;$('#'+source).oninput();};$('#settingsSoundToggle').onchange=()=>{$('#soundToggle').checked=$('#settingsSoundToggle').checked;$('#soundToggle').onchange();};$('#settingsSoundPreview').onclick=auditionSound;$('#resetOffset').onclick=()=>{applyOffset(0);toast('已恢复零补偿。');};$('#quickCalibration').onclick=()=>{openSettings('sound');openCalibration();};$('#openCalibration').onclick=openCalibration;}

function openCalibration(){stopCalibration();$('#startCalibration').textContent='开始校准';$('#calibrationPhase').textContent='准备就绪 · 120 BPM';$('#calibrationResult').textContent=`当前补偿 ${rhythmPrefs.offset} ms。完成后自动填入稳定的校准结果。`;$('#calibrationSamples').replaceChildren();for(let i=0;i<4;i++)$('#calibrationSamples').append(el('span','','第'+(i+1)+'轮 · 等待'));openDialog('#calibrationDialog');}
function stopCalibration(message){if(calibrationTimer!==null){clearInterval(calibrationTimer);calibrationTimer=null;}if(calibration){calibration=null;stopAudio();}$('#calibrationTap').disabled=true;$('#startCalibration').disabled=false;$('#startCalibration').textContent='重新校准';$$('#calibrationBeats span').forEach(n=>n.classList.remove('current'));if(message)$('#calibrationResult').textContent=message;}
function calibrationClick(when,third){const osc=audio.createOscillator(),gain=audio.createGain();osc.frequency.value=third?1200:750;gain.gain.setValueAtTime(0,when);gain.gain.linearRampToValueAtTime(.12,when+.003);gain.gain.exponentialRampToValueAtTime(.0001,when+.075);osc.connect(gain);gain.connect(audio.destination);osc.start(when);osc.stop(when+.09);activeNodes.add(osc);osc.onended=()=>{activeNodes.delete(osc);osc.disconnect();gain.disconnect();};}
async function startCalibration(){stopCalibration();initAudio();if(!audio){$('#calibrationResult').textContent='当前浏览器无法启用声音，未修改原补偿。';return;}$('#startCalibration').disabled=true;$('#calibrationResult').textContent='正在准备节拍声音…';const intent=audioIntent;try{if(audio.state!=='running')await audio.resume();}catch(e){$('#startCalibration').disabled=false;$('#calibrationResult').textContent='声音未能启动，请重试。';return;}if(intent!==audioIntent||!$('#calibrationDialog').open){$('#startCalibration').disabled=false;return;}if(audio.state!=='running'){$('#startCalibration').disabled=false;$('#calibrationResult').textContent='声音尚未就绪，请重试。';return;}
 const startPerf=now()+.5,startAudio=audio.currentTime+.5;calibration={startPerf,startAudio,next:0,samples:[null,null,null,null],missed:new Set(),lastBeat:-1,input:null};$('#calibrationTap').disabled=false;$('#calibrationTap').focus();$('#calibrationResult').textContent='先听示范；随后每轮第三拍按一下，共4次。';$('#calibrationSamples').replaceChildren();for(let i=0;i<4;i++)$('#calibrationSamples').append(el('span','','第'+(i+1)+'轮 · 等待'));calibrationTimer=setInterval(pumpCalibration,20);pumpCalibration();}
function pumpCalibration(){const c=calibration;if(!c)return;if(audio.state!=='running'){stopCalibration('声音播放中断，未修改原补偿，请重试。');return;}const t=now();while(c.next<20&&c.startPerf+c.next*.5<t+.15){const when=c.startAudio+c.next*.5;if(when>audio.currentTime)calibrationClick(when,c.next%4===2);c.next++;}const beat=Math.floor((t-c.startPerf)/.5);if(beat!==c.lastBeat){c.lastBeat=beat;$$('#calibrationBeats span').forEach((n,i)=>n.classList.toggle('current',beat>=0&&beat<20&&i===beat%4));$('#calibrationPhase').textContent=beat<0?'即将开始…':beat<4?'示范轮 · 聆听第三拍':`第 ${Math.min(4,Math.floor(beat/4))} / 4 轮 · 第 ${beat%4+1} 拍`;}
 for(let i=0;i<4;i++){const target=c.startPerf+(6+i*4)*.5;if(c.samples[i]===null&&t>target+.3){c.missed.add(i);const n=$$('#calibrationSamples span')[i];if(n)n.textContent='第'+(i+1)+'轮 · 漏点';}}
 if(t>c.startPerf+9.3||c.samples.every(x=>x!==null))finishCalibration();}
function tapCalibration(input){const c=calibration;if(!c)return;if(c.input&&input!==c.input){$('#calibrationResult').textContent='本轮请保持同一种输入方式：'+(c.input==='keyboard'?'空格键':'点击区域')+'。';return;}const t=now();let target=-1,best=Infinity;for(let i=0;i<4;i++){const d=Math.abs(t-(c.startPerf+(6+i*4)*.5));if(d<=.3&&d<best){best=d;target=i;}}if(target<0){$('#calibrationResult').textContent='请在每轮第三拍按下；示范轮不采样。';return;}if(c.samples[target]!==null){$('#calibrationResult').textContent='本轮已记录，请等待下一轮第三拍。';return;}c.input=input;c.samples[target]=(t-(c.startPerf+(6+target*4)*.5))*1000;const v=Math.round(c.samples[target]),n=$$('#calibrationSamples span')[target];if(n)n.textContent=`第${target+1}轮 · ${v>0?'+':''}${v} ms`;$('#calibrationResult').textContent=`已记录 ${c.samples.filter(x=>x!==null).length} / 4 次 · 请继续跟随声音`;if(c.samples.every(x=>x!==null))finishCalibration();}
function finishCalibration(){if(!calibration)return;const result=Rhythm.estimate(calibration.samples);stopCalibration();$('#calibrationPhase').textContent=result.ok?'校准完成':'需要重试';if(result.ok){applyOffset(result.offset);$('#calibrationResult').textContent=`已自动应用 ${result.offset>0?'+':''}${result.offset} ms · 四次差异 ${result.spread} ms。可以重测或在设置中手动微调。`;toast('延迟补偿已自动保存。');}else $('#calibrationResult').textContent=result.reason+' 原补偿保持不变。';}
function setupCalibration(){$('#startCalibration').onclick=startCalibration;$('#calibrationTap').onpointerdown=e=>{e.preventDefault();if(e.button===0||e.pointerType==='touch')tapCalibration('pointer');};$('#calibrationTap').onclick=e=>{if(e.detail===0)tapCalibration('pointer');};$('#calibrationDialog').addEventListener('close',()=>stopCalibration());window.addEventListener('blur',()=>{if(calibration)stopCalibration('窗口已切换，本次校准取消，原补偿保持不变。');});document.addEventListener('visibilitychange',()=>{if(document.hidden&&calibration)stopCalibration('页面已隐藏，本次校准取消，原补偿保持不变。');});}


// The floating transport mirrors the main button and never becomes a second player.
function mainPlayIsVisible(){const r=$('#playBtn').getBoundingClientRect();return r.width>0&&r.height>0&&r.top>=0&&r.left>=0&&r.bottom<=window.innerHeight&&r.right<=window.innerWidth;}
function updateFloatingPractice(){const button=$('#floatingPractice');if(!button)return;const label=$('#playBtn').textContent;if(button.textContent!==label){button.textContent=label;button.setAttribute('aria-label',label.trim());}const hide=$('#practicePage').hidden||Boolean(pipWindow)||$$('dialog[open]').length>0||mainPlayIsVisible();if(button.hidden!==hide)button.hidden=hide;}
function alignPracticeStage(){if(pipWindow||$('#practicePage').hidden||document.hidden)return;const stage=$('#practiceStage');if(!stage)return;const top=Math.max(0,window.scrollY+stage.getBoundingClientRect().top);const reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;window.scrollTo?.({top,behavior:reduce?'instant':'smooth'});}
function setupPracticeAccess(){$('#floatingPractice').onclick=start;const refresh=()=>updateFloatingPractice();if(typeof IntersectionObserver!=='undefined'){const observer=new IntersectionObserver(refresh,{threshold:[0,.99,1]});observer.observe($('#playBtn'));}window.addEventListener('scroll',refresh,{passive:true});window.addEventListener('resize',refresh);$$('dialog').forEach(d=>d.addEventListener('close',refresh));if(typeof MutationObserver!=='undefined')new MutationObserver(refresh).observe(document.body,{attributes:true,subtree:true,attributeFilter:['open','hidden']});refresh();}
